SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `events`;

CREATE TABLE events (
	id INTEGER NOT NULL AUTO_INCREMENT,
	event_id VARCHAR(50),
	name VARCHAR(200) NOT NULL,
	description TEXT,
	dispute_type VARCHAR(100),
	our_side JSON,
	opponent_side JSON,
	legal_systems JSON,
	fact_summary TEXT,
	opponent_stance_preset TEXT,
	opponent_claims_options JSON,
	opponent_legal_system VARCHAR(50),
	created_at DATETIME,
	updated_at DATETIME,
	PRIMARY KEY (id)
);
CREATE UNIQUE INDEX ix_events_event_id ON events (event_id);
CREATE INDEX ix_events_id ON events (id);
DROP TABLE IF EXISTS `agents`;

CREATE TABLE agents (
	id INTEGER NOT NULL AUTO_INCREMENT,
	agent_id VARCHAR(50),
	name VARCHAR(100) NOT NULL,
	description TEXT,
	mission TEXT,
	responsibilities TEXT,
	agent_type VARCHAR(7) NOT NULL,
	event_id INTEGER,
	system_prompt TEXT,
	stance TEXT,
	goals JSON,
	strategy_orientation VARCHAR(50),
	legal_priority VARCHAR(50),
	knowledge_scope JSON,
	llm_config JSON,
	template_id VARCHAR(50),
	is_active BOOL,
	created_at DATETIME,
	updated_at DATETIME,
	PRIMARY KEY (id),
	FOREIGN KEY(event_id) REFERENCES events (id)
);
CREATE UNIQUE INDEX ix_agents_agent_id ON agents (agent_id);
CREATE INDEX ix_agents_id ON agents (id);
DROP TABLE IF EXISTS `laws`;

CREATE TABLE laws (
	id INTEGER NOT NULL AUTO_INCREMENT,
	code VARCHAR(50),
	name_zh VARCHAR(200) NOT NULL,
	name_en VARCHAR(200),
	category VARCHAR(50),
	level VARCHAR(50),
	region VARCHAR(50),
	content TEXT,
	summary TEXT,
	source_url VARCHAR(200),
	effective_date DATETIME,
	updated_at DATETIME,
	PRIMARY KEY (id)
);
CREATE UNIQUE INDEX ix_laws_code ON laws (code);
CREATE INDEX ix_laws_id ON laws (id);
DROP TABLE IF EXISTS `plans`;

CREATE TABLE plans (
	id INTEGER NOT NULL AUTO_INCREMENT,
	plan_id VARCHAR(50),
	name VARCHAR(200) NOT NULL,
	event_id INTEGER,
	content_md TEXT,
	action_paths JSON,
	risk_assessment JSON,
	legal_basis JSON,
	feasibility_score FLOAT,
	risk_score FLOAT,
	overall_score FLOAT,
	status VARCHAR(20),
	is_optimized BOOL,
	parent_plan_id VARCHAR(50),
	created_at DATETIME,
	updated_at DATETIME,
	PRIMARY KEY (id),
	FOREIGN KEY(event_id) REFERENCES events (id)
);
CREATE INDEX ix_plans_id ON plans (id);
CREATE UNIQUE INDEX ix_plans_plan_id ON plans (plan_id);
DROP TABLE IF EXISTS `simulations`;

CREATE TABLE simulations (
	id INTEGER NOT NULL AUTO_INCREMENT,
	session_id VARCHAR(50),
	plan_id INTEGER,
	blue_agent_config JSON,
	red_agent_config JSON,
	judge_agent_config JSON,
	params JSON,
	status VARCHAR(10),
	current_round INTEGER,
	win_rate FLOAT,
	total_rounds INTEGER,
	evidence_stats JSON,
	final_result JSON,
	optimized_plan_id VARCHAR(50),
	started_at DATETIME,
	completed_at DATETIME,
	created_at DATETIME,
	PRIMARY KEY (id),
	FOREIGN KEY(plan_id) REFERENCES plans (id)
);
CREATE INDEX ix_simulations_id ON simulations (id);
CREATE UNIQUE INDEX ix_simulations_session_id ON simulations (session_id);
DROP TABLE IF EXISTS `simulation_rounds`;

CREATE TABLE simulation_rounds (
	id INTEGER NOT NULL AUTO_INCREMENT,
	simulation_id INTEGER,
	round_number INTEGER NOT NULL,
	blue_argument TEXT,
	blue_legal_basis JSON,
	red_argument TEXT,
	red_legal_basis JSON,
	red_risks_raised JSON,
	judge_ruling TEXT,
	judge_score JSON,
	win_rate_before FLOAT,
	win_rate_after FLOAT,
	win_rate_delta FLOAT,
	created_at DATETIME,
	PRIMARY KEY (id),
	FOREIGN KEY(simulation_id) REFERENCES simulations (id)
);
CREATE INDEX ix_simulation_rounds_id ON simulation_rounds (id);

INSERT INTO `events` (`id`, `event_id`, `name`, `description`, `dispute_type`, `our_side`, `opponent_side`, `legal_systems`, `fact_summary`, `opponent_stance_preset`, `opponent_claims_options`, `opponent_legal_system`, `created_at`, `updated_at`) VALUES
(1, 'evt-compliance-001', '某互联网公司违规收集用户个人信息案', '深圳某互联网公司在未明确告知用户的情况下，违规收集用户位置、通讯录等敏感个人信息，被监管部门立案调查。', '数据安全', '["企业法务部", "合规委员会"]', '["国家互联网信息办公室", "用户维权代表"]', '["《个人信息保护法》", "《网络安全法》", "《数据安全法》"]', '企业APP在用户未明确同意情况下调用位置权限，并将数据共享给第三方广告平台，监管部门依据《个人信息保护法》第17条启动执法程序。', '监管部门主张企业违反了告知同意原则，收集超出业务必要范围，应依法承担行政责任并整改。', '["违反最小必要原则", "未履行告知义务", "非法向第三方提供个人信息", "未建立个人信息保护管理制度"]', 'cn_data_law', '2026-03-19 23:44:42', '2026-04-21 23:44:42'),
(2, 'evt-compliance-002', '制造企业拖欠农民工工资劳动仲裁案', '广州某制造企业因资金周转困难，拖欠200余名农民工约380万元工资，劳动者集体申请劳动仲裁。', '劳动合规', '["企业法务部", "人力资源部"]', '["劳动仲裁委员会", "农民工代表团"]', '["《劳动合同法》", "《工资支付暂行规定》", "《保障农民工工资支付条例》"]', '企业因订单下滑资金紧张，连续3个月未足额发放工资。劳动者向仲裁委提出仲裁申请，要求支付拖欠工资及经济补偿金。', '劳动者主张依据《劳动合同法》第85条，要求企业按应付金额50%-100%加付赔偿金，并追究企业负责人法律责任。', '["拖欠工资违法", "要求加付赔偿金", "申请先予执行", "追究刑事责任"]', 'cn_labor_law', '2026-04-07 23:44:42', '2026-04-21 23:44:42'),
(3, 'evt-compliance-003', '电商平台二选一不正当竞争纠纷', '某头部电商平台要求入驻商家签署独家合作协议，禁止商家同时在竞争平台销售，引发反垄断调查。', '竞争合规', '["企业法务部", "外部律所"]', '["国家市场监督管理总局", "受损商家联合会"]', '["《反垄断法》", "《反不正当竞争法》", "《电子商务法》"]', '监管部门认定该平台滥用市场支配地位，强迫经营者进行二选一，违反《反垄断法》第22条，启动行政处罚程序。', '监管方认为企业具有市场支配地位，其独家合作要求构成滥用市场支配地位行为，应依法处以营业额1%-10%的罚款。', '["滥用市场支配地位", "限制市场竞争", "损害商家利益", "违反公平竞争原则"]', 'cn_competition_law', '2026-02-25 23:44:42', '2026-04-21 23:44:42'),
(4, 'evt-compliance-004', '软件公司商业秘密泄露侵权案', '北京某软件公司前核心技术员工离职后加入竞争对手，将原公司核心算法及客户数据带走使用，原公司提起诉讼。', '知识产权', '["原告企业法务部", "知识产权律所"]', '["被告前员工", "竞争对手公司"]', '["《反不正当竞争法》", "《劳动合同法》", "《刑法》第219条"]', '被告离职前通过公司内网下载大量源代码及客户数据库，入职新公司后用于同类产品开发。原告申请证据保全并提起诉讼，索赔500万元。', '被告主张涉案技术属于个人技能积累，客户信息系合法获取，不构成侵犯商业秘密，请求驳回原告全部诉求。', '["否认商业秘密性质", "主张个人技能积累", "技术公知域抗辩", "无损害结果抗辩"]', 'cn_ip_law', '2026-04-04 23:44:42', '2026-04-21 23:44:42'),
(5, 'evt-compliance-005', '建筑企业挂靠承包合同纠纷', '上海某建筑公司以挂靠方式承接工程项目，工程质量不合格引发业主索赔，被挂靠单位与实际施工方责任划分产生争议。', '合同纠纷', '["被挂靠建筑公司法务部"]', '["业主方", "实际施工团队"]', '["《建筑法》", "《民法典》合同编", "《建设工程施工合同司法解释》"]', '实际施工人以被挂靠企业名义签订合同，工程完工后出现重大质量问题，业主要求连带赔偿2000万元，被挂靠企业与实际施工方互相推诿责任。', '业主方主张被挂靠企业与实际施工人应承担连带责任，要求二者共同承担质量损失赔偿及工期违约金。', '["连带责任主张", "合同无效抗辩", "工程质量鉴定申请", "索赔施工损失"]', 'cn_civil_law', '2026-04-09 23:44:42', '2026-04-21 23:44:42'),
(6, 'evt-compliance-006', '上市公司信息披露违规证券处罚案', '杭州某上市公司在年报中虚增营业收入约3亿元，隐瞒重大关联交易，证监会立案调查并拟处以行政处罚。', '证券合规', '["上市公司法务部", "独立董事"]', '["中国证券监督管理委员会", "投资者保护机构"]', '["《证券法》", "《上市公司信息披露管理办法》", "《刑法》第160条"]', '证监会调查发现，公司通过虚构销售合同虚增收入，并未在年报中如实披露控股股东占用资金情况，导致股价异常波动，众多投资者受损。', '证监会认定公司存在信息披露虚假陈述，拟对公司处以顶格罚款1000万元，并对相关责任人采取市场禁入措施。', '["虚假陈述违法", "要求高管承担连带责任", "投资者损失赔偿请求", "撤销相关股权激励"]', 'cn_securities_law', '2026-03-30 23:44:42', '2026-04-21 23:44:42'),
(7, 'evt-compliance-007', '食品企业产品质量安全违规案', '成都某食品公司生产的产品被检测出食品添加剂超标，多名消费者投诉后市场监管部门介入检查，企业面临召回和处罚。', '食品安全', '["企业法务部", "质量管理部"]', '["市场监督管理局", "消费者协会"]', '["《食品安全法》", "《产品质量法》", "《消费者权益保护法》"]', '抽样检测发现企业旗下零食产品中防腐剂苯甲酸钠含量超国家标准2.3倍，监管部门依法要求停产整改、召回全部问题产品，消费者提出索赔诉求。', '监管部门依据《食品安全法》第124条，主张对企业处以货值金额5-10倍罚款，吊销食品生产许可证，并追究相关负责人责任。', '["产品质量不合格", "要求停产召回", "行政处罚依据", "消费者赔偿请求"]', 'cn_food_law', '2026-01-22 23:44:42', '2026-04-21 23:44:42'),
(8, 'evt-compliance-008', '科技公司员工竞业限制协议纠纷', '武汉某科技公司前高管离职后3个月即加入同行业竞争公司，原公司依据竞业限制协议申请劳动仲裁要求支付违约金。', '劳动合规', '["原告企业法务部"]', '["前高管", "竞争对手公司"]', '["《劳动合同法》第23-24条", "《劳动争议调解仲裁法》"]', '离职前高管签署了为期2年、月补偿金5000元的竞业限制协议，离职后仅3个月加入竞争对手，原公司依据协议主张违约金30万元。', '前高管主张竞业限制范围过宽，补偿金标准过低不具约束力，且新公司业务与原公司不存在实质竞争关系，请求认定协议无效。', '["限制范围过宽抗辩", "补偿金不足抗辩", "非竞争业务抗辩", "协议无效主张"]', 'cn_labor_law', '2026-04-19 23:44:42', '2026-04-21 23:44:42'),
(9, 'evt-compliance-009', '房地产公司违规预售商品房案', '南京某房地产公司在未取得预售许可证的情况下，通过【认筹】方式变相收取购房款约1.2亿元，被住建部门查处。', '合同纠纷', '["房产公司法务部"]', '["住房和城乡建设局", "购房者代表"]', '["《城市商品房预售管理办法》", "《房地产管理法》", "《民法典》"]', '该公司以【内部认筹】名义向500余名购房者收取定金，但实际未办理预售许可，购房者要求退款并支付利息损失，监管部门予以行政处罚。', '购房者主张合同无效，要求退还全部款项并按银行贷款利率赔偿资金占用损失；监管部门处以5倍以下罚款。', '["违规预售违法", "合同无效请求", "退款及利息赔偿", "行政罚款处罚"]', 'cn_civil_law', '2026-02-16 23:44:42', '2026-04-21 23:44:42'),
(10, 'evt-compliance-010', '跨国企业跨境数据传输合规审查案', '某跨国公司将中国用户数据传输至境外服务器处理，未按规定进行数据出境安全评估，被网信部门责令整改。', '数据安全', '["企业数据合规部", "外部专项律所"]', '["国家互联网信息办公室", "地方网信办"]', '["《数据安全法》", "《个人信息保护法》", "《数据出境安全评估办法》"]', '该公司将超过100万条中国用户个人信息及重要数据传输至境外服务器，未事先向网信办申报数据出境安全评估，被发现后面临整改和罚款。', '网信部门认定企业违反数据本地化要求及数据出境管理规定，责令限期整改，并依法处以100万以上罚款，情节严重可暂停数据处理活动。', '["违反数据出境规定", "未履行安全评估义务", "数据本地化要求", "责令整改停止违规"]', 'cn_data_law', '2026-04-15 23:44:42', '2026-04-21 23:44:42'),
(11, 'evt-compliance-011', '医药企业商业贿赂合规调查案', '重庆某医药公司被举报通过讲课费、学术会议等方式向医生行贿以推广处方药，国家卫健委及市场监管局联合调查。', '商业合规', '["企业合规部", "法务部"]', '["国家卫生健康委员会", "市场监督管理局"]', '["《反不正当竞争法》", "《药品管理法》", "《刑法》第163条"]', '调查发现该公司2020-2025年间累计向200余名医生支付超过1500万元的不正当利益，通过药品销量提成、虚假学术会议等方式进行商业贿赂。', '监管部门认定企业行为构成商业贿赂，违反《反不正当竞争法》第7条，拟处以违法所得1-3倍罚款，并将相关责任人移送司法机关。', '["商业贿赂违法认定", "没收违法所得", "行政罚款处罚", "刑事责任追究"]', 'cn_competition_law', '2026-04-06 23:44:42', '2026-04-21 23:44:42'),
(12, 'evt-compliance-012', '物流公司劳务外包员工工伤认定纠纷', '广州某物流公司快递员在配送途中发生交通事故受伤，因劳务外包关系复杂，工伤认定及赔偿责任归属产生争议。', '劳动合规', '["物流公司法务部"]', '["受伤快递员", "劳动保障行政部门"]', '["《工伤保险条例》", "《劳动合同法》", "《最高人民法院关于审理工伤保险行政案件若干问题的规定》"]', '受伤快递员与劳务派遣公司签订合同，实际在物流公司平台工作。工伤认定机构认定工伤后，用工单位、派遣公司、平台三方对赔偿责任互相推诿，劳动者维权困难。', '劳动者主张实际用工的物流平台公司应承担工伤赔偿连带责任，不应因外包形式规避雇主法律义务。', '["认定劳动关系", "要求连带赔偿", "工伤医疗费用承担", "停工留薪期工资请求"]', 'cn_labor_law', '2026-02-07 23:44:42', '2026-04-21 23:44:42'),
(13, 'evt-compliance-013', '网络平台算法歧视消费者权益案', '某外卖平台被曝光对新老用户实施差异化定价，老用户反而比新用户支付更高配送费，引发消费者投诉和监管关注。', '消费者权益', '["平台法务部", "算法合规团队"]', '["消费者权益保护委员会", "市场监督管理局"]', '["《消费者权益保护法》", "《互联网信息服务算法推荐管理规定》", "《价格法》"]', '平台通过用户画像对消费能力强的老用户实施价格歧视，相同订单老用户配送费高出新用户30%-50%，消费者协会收到大量投诉后向监管部门举报。', '监管部门认定平台价格歧视行为违反公平交易原则，损害消费者合法权益，要求整改并处以相应行政处罚，同时责令公开算法规则。', '["价格歧视违法", "算法透明度要求", "消费者损失赔偿", "整改算法推荐规则"]', 'cn_consumer_law', '2026-03-06 23:44:42', '2026-04-21 23:44:42');
INSERT INTO `agents` (`id`, `agent_id`, `name`, `description`, `mission`, `responsibilities`, `agent_type`, `event_id`, `system_prompt`, `stance`, `goals`, `strategy_orientation`, `legal_priority`, `knowledge_scope`, `llm_config`, `template_id`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'AGENT-LABOR-LAW', '劳动合规顾问-张律师', '专注劳动合同法、工资支付规定、竞业限制及工伤认定等劳动用工合规领域，擅长处理劳动仲裁及诉讼案件，为企业提供劳动风险防控建议。', '基于劳动法律体系，为我方在拖欠工资、竞业限制、工伤认定等劳动争议中提供系统性法律支持，降低企业用工法律风险。', '1. 分析劳动合同条款合规性，识别用工风险点。
2. 针对竞业限制纠纷，评估协议有效性与违约金合理性。
3. 处理工伤认定程序，厘清劳务外包关系下的责任主体。
